// Lee el CSV (export contable separado por ';') y lo convierte en
// una lista de productos. Misma lógica que el catálogo que ya funciona.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const text = buffer.toString('utf8');

function round100(n){ return Math.round(n/100)*100; }
function cleanPrice(raw){
  if(!raw) return null;
  let s = String(raw).replace(/\s/g,'').replace(/\$/g,'');
  if(s==='' || s==='-') return null;
  const intDigits = ((s.split(',')[0]).match(/\d+/g) || []).join('');
  if(!intDigits) return null;
  const n = parseInt(intDigits, 10);
  if(!n) return null;
  return round100(n);
}
function cleanGroup(g){
  return (g||'').replace(/^\s*\d+\s*-\s*/,'').trim().toUpperCase() || 'SIN GRUPO';
}

const parts = text.split('P-Producto;');
const productos = [];
let idc = 0;
for (let i = 0; i < parts.length; i++) {
  const chunk = parts[i];
  if (!chunk || chunk.indexOf(';') === -1) continue;
  const f = chunk.split(';');
  const grpRaw = (f[0] || '').trim();
  if (!/^\d+\s*-/.test(grpRaw)) continue;   // descarta el encabezado
  const nombre = (f[2] || '').trim();
  if (!nombre) continue;
  const precio = cleanPrice(f[34]);          // campo PRECIO DE VENTA
  productos.push({
    id: (f[1] || idc).toString().trim(),
    nombre,
    precio,
    grupo: cleanGroup(grpRaw)
  });
  idc++;
}

return [{ json: { productos, total: productos.length } }];
